"""iOS stub for the C ``_multiprocessing`` extension.

CPython cannot build ``_multiprocessing`` for iOS (the sandbox has no ``fork``
and no POSIX unnamed semaphores), so it is absent from the bundled interpreter.
Blender's extensions add-on (``bl_pkg``) imports ``multiprocessing.synchronize``
at startup for a *type annotation* but never actually spawns processes on iOS, so
satisfying the import is all that is required. Any real use raises a clear error
rather than a cryptic ``ModuleNotFoundError``.
"""

SEM_VALUE_MAX = 2147483647


def _unavailable(*args, **kwargs):
    raise OSError("multiprocessing is not available on iOS")


class SemLock:
    SEM_VALUE_MAX = SEM_VALUE_MAX

    def __init__(self, *args, **kwargs):
        _unavailable()

    @classmethod
    def _rebuild(cls, *args, **kwargs):
        _unavailable()


def sem_unlink(_name):
    pass


# A few multiprocessing submodules import these names directly; provide inert
# placeholders so the imports succeed (instantiation raises like SemLock).
class Connection:
    def __init__(self, *args, **kwargs):
        _unavailable()


class PipeConnection:
    def __init__(self, *args, **kwargs):
        _unavailable()
